// Generated by tools/gen_file_close_matrix.py; change the generator, not this file.
// Icarus Verilog 14.0 devel writes the pending $fstrobe of s2 into the file opened
// under the freed number; 21.3.1 has $fclose cancel it (SYSTEM_TASKS.md 6.2).
`timescale 1ns/1ns
module top;
  integer d, e;
  reg [7:0] v;
  task show(input string name);
    integer r, n;
    string line;
    r = $fopen(name, "r");
    n = $fgets(line, r);
    while (n > 0) begin
      $write("%s: %s", name, line);
      n = $fgets(line, r);
    end
    $display("%s: end", name);
    $fclose(r);
  endtask
  initial begin
    d = $fopen("s1.txt", "w");
    $fstrobe(d, "s1 strobe");
    $fclose(d);
    #1 show("s1.txt");
    d = $fopen("s2a.txt", "w");
    $fstrobe(d, "s2 strobe");
    $fclose(d);
    e = $fopen("s2b.txt", "w");
    $display("s2 reused %0d", e == d);
    #1 $fclose(e);
    show("s2a.txt");
    show("s2b.txt");
    v = 1;
    d = $fopen("m1.txt", "w");
    $fmonitor(d, "m1 v=%0d", v);
    #1 v = 2;
    #1 $fclose(d);
    #1 v = 3;
    #1 show("m1.txt");
    v = 1;
    d = $fopen("m2a.txt", "w");
    $fmonitor(d, "m2 v=%0d", v);
    #1 $fclose(d);
    e = $fopen("m2b.txt", "w");
    $display("m2 reused %0d", e == d);
    v = 2;
    #1 v = 3;
    #1 $fclose(e);
    show("m2a.txt");
    show("m2b.txt");
  end
endmodule
